/**
 * Brand marks.
 *
 * Path data from Simple Icons (https://simpleicons.org), which is CC0, so it can be
 * embedded rather than fetched: no network request when the dashboard loads, and no
 * broken images on a server with no way out to the internet. The brands themselves
 * remain the property of their owners, and are used here only to label the thing they
 * are.
 *
 * Generated once and committed on purpose. A build step that reaches the network is a
 * build step that fails on a train.
 */
export interface BrandMark {
  title: string;
  /** The brand's own colour, used as the tile background. */
  hex: string;
  /** A single path, drawn in a 24x24 box unless `viewBox` says otherwise. */
  path: string;
  /** For marks that were not drawn on a 24x24 grid. */
  viewBox?: string;
  /** Some marks are drawn expecting the even-odd rule and are solid blobs without it. */
  evenOdd?: boolean;
  /**
   * A mark that is a picture rather than a silhouette, given as the inside of an
   * `<svg>` with its own viewBox. Set this and the tile stops recolouring anything
   * and just frames it: a lobster is not improved by being flattened to one colour.
   */
  art?: { viewBox: string; svg: string };
}

/**
 * Two are not from Simple Icons, which does not carry either: OpenClaw and Hermes
 * Agent both come from dashboardicons.com, which does. Hermes is a silhouette and
 * behaves like every other mark here. OpenClaw is a small painting of a lobster,
 * gradients and all, so it is kept as it was drawn rather than flattened into one
 * colour to fit a format.
 */
